DECLARE @doc JSON = '{
  "orderId": 7, "customer": {"name": "Sara"},
  "items": [ {"sku":"A1","qty":2}, {"sku":"B9","qty":1} ]
}';

SELECT o.orderId, o.customerName, i.sku, i.qty
FROM OPENJSON(@doc)
     WITH (orderId INT,
           customerName NVARCHAR(100) '$.customer.name',
           items NVARCHAR(MAX) AS JSON) AS o
CROSS APPLY OPENJSON(o.items)
     WITH (sku VARCHAR(10), qty INT) AS i;
